// npm install druxt-site @druxt-contrib/node-preview
export default {
  modules: ['@druxt-contrib/node-preview', 'druxt-site'],
  druxt: {
    baseUrl: 'https://cms.example.com',
    proxy: { api: true },
    nodePreview: {
      layouts: ['default', 'preview'],
      register: {
        url: 'https://example.vercel.app',
        consumer: 'my-frontend', // The consumer's client ID.
        token: true,
      },
    },
  },
}

// Runs in the browser: the fragment never reaches a server.
// The origins this page may fetch a preview from.
const allowed = ['https://cms.example.com']

// Some routers turn https:// into https:/ inside a hash.
const hash = decodeURIComponent(location.hash.slice(1))
const [address, token] = hash
  .replace(/^(https?):\/(?!\/)/, '$1://')
  .split(';token=')
const endpoint = new URL(address)

if (!allowed.includes(endpoint.origin)) {
  throw new Error(`Refusing a preview from ${endpoint.origin}`)
}

const response = await fetch(endpoint, {
  // A token target reads without the cookie.
  credentials: token ? 'omit' : 'include',
  headers: {
    Accept: 'application/vnd.api+json',
    ...(token && { Authorization: `Bearer ${token}` }),
  },
})
if (!response.ok) throw new Error(`Preview failed: HTTP ${response.status}`)
const { data, included } = await response.json()
